const fs = require('fs');
const path = require('path');
const { fileURLToPath } = require('url');

// Get the directory name of the current module
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Reads all SQL migration files from the migrations directory and logs them in order
 */
async function migrate() {
  // Define the migrations directory path
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if the migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory not found at "${migrationsDir}"`);
    process.exit(1);
  }

  // Get all SQL files from the migrations directory
  const files = fs.readdirSync(migrationsDir)
    .filter(file => file.endsWith('.sql'))
    // Sort files chronologically (handles numeric prefixes like 001, 002, etc.)
    .sort((a, b) => {
      // Extract numeric prefixes if present
      const parsePrefix = (filename) => {
        const match = filename.match(/^(\d{3,})_/);
        return match ? parseInt(match[1], 10) : 0;
      };

      const prefixA = parsePrefix(a);
      const prefixB = parsePrefix(b);

      if (prefixA !== prefixB) {
        return prefixA - prefixB;
      }
      // If prefixes are equal, fall back to string comparison
      return a.localeCompare(b);
    });

  // Log the migrations that would be applied
  console.log('\n📋 Pending Migrations:');
  console.log('=====================\n');

  if (files.length === 0) {
    console.log('No SQL files found in the migrations directory.');
  } else {
    files.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
    console.log(`\nTotal migrations: ${files.length}`);
  }

  return files;
}

/**
 * Execute the migration script
 */
if (require.main === module) {
  migrate()
    .then(files => {
      if (files.length > 0) {
        console.log('\n✅ Migration order verified.');
      }
      process.exit(0);
    })
    .catch(error => {
      console.error('❌ Error:', error.message);
      process.exit(1);
    });
}

module.exports = migrate;

