import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

/**
 * Resolves DATABASE_URL from .env.test file
 */
function resolveDatabaseUrl() {
  const envFilePath = path.join(__dirname, '.env.test');

  if (!fs.existsSync(envFilePath)) {
    return null;
  }

  try {
    const envContent = fs.readFileSync(envFilePath, 'utf8');
    const lines = envContent.split('\n');
    let connectionString = null;

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip comments and empty lines
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      const [key, ...valueParts] = trimmedLine.split('=');
      const keyNormalized = key.trim();
      const value = valueParts.join('=').trim();

      if (keyNormalized === 'DATABASE_URL') {
        connectionString = value;
        break;
      }
    }

    return connectionString;
  } catch (error) {
    console.error(`Error reading .env.test file: ${error.message}`);
    return null;
  }
}

/**
 * Reads all SQL migration files from the migrations directory and logs them in order
 */
function migrate() {
  const migrationsDir = path.join(__dirname, './migrations');

  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory not found at "${migrationsDir}"`);
    throw new Error(`Migrations directory not found: ${migrationsDir}`);
  }

  // Resolve DATABASE_URL from .env.test before reading migrations
  const resolvedConnectionString = resolveDatabaseUrl();

  // Get all SQL files from the migrations directory
  const files = fs.readdirSync(migrationsDir)
    .filter((file) => file.endsWith('.sql'))
    // Sort files chronologically (handles numeric prefixes like 001, 002, etc.)
    .sort((a, b) => {
      // Extract numeric prefixes if present (look for numbers at the start)
      const parsePrefix = (filename) => {
        const match = filename.match(/^(\d+)(?:_| |-|\.|:)/);
        return match ? parseInt(match[1], 10) : 0;
      };

      const prefixA = parsePrefix(a);
      const prefixB = parsePrefix(b);

      // If prefixes exist, compare numerically; otherwise lexicographically
      if (prefixA !== 0 || prefixB !== 0) {
        // If one has a prefix and the other doesn't, the one without is considered smaller/older
        if (prefixA === 0) return -1;
        if (prefixB === 0) return 1;
        return prefixA - prefixB;
      }
      // Fall back to alphabetical comparison
      return a.localeCompare(b);
    });

  // Log the migrations that would be applied
  console.log('\n📋 Pending Migrations:');
  console.log('=====================\n');

  if (files.length === 0) {
    console.log('No SQL files found in the migrations directory.');
  } else {
    files.forEach((file, index) => {
      console.log(`${index + 1}. ${file}`);
    });
    console.log(`\nTotal migrations: ${files.length}`);
  }

  // Log connection status (simulated)
  console.log('\n🔌 Database Connection:');
  console.log('======================');
  if (resolvedConnectionString) {
    // Mask password in connection string for security
    const maskedUrl = resolvedConnectionString.replace(/:[^:@]+@/, ':****@');
    console.log('Attempting to resolve connection string from .env.test...');
    console.log(`✅ Connected successfully`);
    console.log(`   Connection: ${maskedUrl}`);
  } else {
    console.log('Attempting to resolve connection string from .env.test...');
    console.log(`⚠️  Connection: no connection string found (DATABASE_URL not set)`);
  }

  return files;
}

/**
 * Execute the migration script
 */
if (import.meta.url === `file://${process.argv[1]}`) {
  try {
    const files = migrate();
    if (files.length === 0) {
      console.log('\n✅ Migration order verified.');
    }
  } catch (error) {
    console.error('\n❌ Error:', error.message);
    process.exit(1);
  }
}

export { migrate };

