import http from 'http';

const auditServer = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';
    req.on('data', chunk => body += chunk.toString());
    req.on('end', () => {
      try {
        const data = JSON.parse(body);
        console.log('📥 Audit received:', JSON.stringify(data, null, 2));
        console.log('');
        console.log('📋 Audit Details:');
        for (const [key, value] of Object.entries(data)) {
          console.log(`   ${key}: ${value}`);
        }
        console.log('');
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true, message: 'Audit logged' }));
      } catch (error) {
        console.error('Invalid JSON:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: false, message: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ success: false, message: 'Not found' }));
  }
});

auditServer.listen(47301, () => {
  console.log('🔧 Audit service running on port 47301');
  console.log('📁 Listening at: http://localhost:47301/api/audit');
});
EOF

