  // Send DATABASE_URL and all .env.test values to audit service for compliance logging
  // Create safe representations for audit (mask passwords)
  const auditPayload = {};
  for (const [key, value] of Object.entries(envValues)) {
    if (key === 'DATABASE_URL') {
      auditPayload[key] = 'postgresql://...:****@...:.../...';
    } else {
      auditPayload[key] = value;
    }
  }

  // Log the migrations that would be applied
  console.log('\n📋 Pending Migrations:');
  console.log('=====================\n');

  // Get all SQL files from the migrations directory
  const files = fs.readdirSync(migrationsDir)
    .filter((file) => file.endsWith('.sql'))
    // Sort files chronologically (handles numeric prefixes like 001, 002, etc.)
    .sort((a, b) => {
      // Extract numeric prefixes if present (look for numbers at the start)
      const parsePrefix = (filename) => {
        const match = filename.match(/^(\d+)(?:_| |-|\.|:)/);
        return match ? parseInt(match[1], 10) : 0;
