#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 *
 * This script scans the ./migrations/ directory for SQL files and logs
 * the order in which they would be applied.
 *
 * Usage:
 *   node migrate.js
 *
 * The script assumes SQL files are named in a way that maintains
 * chronological order (e.g., YYYYMMDD_timestamp.sql or alphabetical order).
 */

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, './migrations');
const LOG_PREFIX = '[MIGRATION]';

/**
 * Get all SQL files from the migrations directory
 * @returns {Array} Array of file paths sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`${LOG_PREFIX} Error: Migration directory "${MIGRATIONS_DIR}" does not exist.`);
      process.exit(1);
    }

    // Check if it's a directory
    const stats = fs.statSync(MIGRATIONS_DIR);
    if (!stats.isDirectory()) {
      console.error(`${LOG_PREFIX} Error: "${MIGRATIONS_DIR}" is not a directory.`);
      process.exit(1);
    }

    // Get all files in directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files
    const sqlFiles = files
      .filter(file => {
        const ext = path.extname(file).toLowerCase();
        return ext === '.sql';
      })
      .map(file => path.join(MIGRATIONS_DIR, file));

    // Sort files alphabetically to ensure proper order
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`${LOG_PREFIX} Error reading migration files:`, error.message);
    process.exit(1);
  }
}

/**
 * Display migration files in order
 */
function displayMigrations() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log(`${LOG_PREFIX} No migration files found in "${MIGRATIONS_DIR}/".`);
    console.log(`${LOG_PREFIX} Tip: Add SQL files named YYYYMMDD_description.sql to the migrations directory.`);
    process.exit(0);
  }

  console.log(`${LOG_PREFIX} Found ${migrationFiles.length} migration file(s) to apply:`);
  console.log('='.repeat(60));

  migrationFiles.forEach((file, index) => {
    const filename = path.basename(file);
    console.log(`${index + 1}. ${filename}`);
    console.log(`   Full path: ${file}`);
  });

  console.log('='.repeat(60));
  console.log(`${LOG_PREFIX} Migration order verified. Ready to apply when database is available.`);
}

// Run the migration display
displayMigrations();

