      return false;
    }

    const auditResponse = await response.json();
    console.log(`${LOG_PREFIX} ✓ Audit successful:`, auditResponse.message || auditResponse);
    return true;
  } catch (error) {
    console.warn(`${LOG_PREFIX} ⚠️  Audit service timeout or error:`, error.message);
    console.warn(`${LOG_PREFIX} Continuing migration check despite audit failure.`);
    return false;
  }
}

/**
 * Get IP address for audit logging (mock implementation)
 * @returns {string} IP address
 */
function getIpAddress() {
  // In production, this would come from a proper source
  // e.g., req.socket.remoteAddress, process.env.FORWARDED_FOR, etc.
  return process.env.REMOTE_ADDR || '127.0.0.1';
}

/**
 * Get client user agent for audit logging
 * @returns {string} User agent
 */
function getClientUserAgent() {
  return process.env.USER_AGENT || 'node-migrate-script';
}

/**
 * Get environment variables for audit logging
 * @returns {Object} Environment variables (excluding sensitive fields)
 */
function getAuditMetadata() {
  const envVars = process.env;

  // Filter out sensitive/unnecessary fields
  const metadata = {};
  const sensitiveKeys = ['DATABASE_URL', 'PASSWORD', 'SECRET', 'TOKEN', 'API_KEY', 'PRIVATE_KEY'];
  const excludeKeys = new Set([...sensitiveKeys, 'USER_AGENT', 'REMOTE_ADDR', 'NODE_ENV', 'PATH', 'PWD', 'HOME']);

  for (const [key, value] of Object.entries(envVars)) {
    if (!excludeKeys.has(key)) {
