const fs = require('fs');
const path = require('path');

// Simple dotenv implementation (in production, use the dotenv package)
function loadEnv(path) {
  if (fs.existsSync(path)) {
    const content = fs.readFileSync(path, 'utf8');
    const lines = content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#') && !trimmed.startsWith('//')) {
        const equalsIndex = trimmed.indexOf('=');
        if (equalsIndex > 0) {
          const key = trimmed.substring(0, equalsIndex).trim();
          let value = trimmed.substring(equalsIndex + 1).trim();
          // Remove quotes if present
          if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
            value = value.substring(1, value.length - 1);
          }
          process.env[key] = value;
        }
      }
    }
  }
}

// Load environment variables
const envPath = path.join(__dirname, '.env.test');
loadEnv(envPath);

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, './migrations');
const LOG_PREFIX = '[MIGRATION]';
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Audit logging through compliance service
 */
async function sendToAuditService(metadata) {
  console.log(`${LOG_PREFIX} Sending audit data to compliance service...`);

  try {
    const auditData = {
      event: 'migration_start',
      timestamp: new Date().toISOString(),
      environment: 'test',
      metadata: metadata,
      sourceIp: process.env.REMOTE_ADDR || '127.0.0.1',
      userAgent: process.env.USER_AGENT || 'node-migrate-script'
    };

    console.log(`${LOG_PREFIX} Payload for ${AUDIT_SERVICE_URL}:`, JSON.stringify(auditData, null, 2));

    const response = await fetch(AUDIT_SERVICE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(auditData)
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.warn(`${LOG_PREFIX} ⚠️  Audit service responded with status ${response.status}: ${errorText}`);
      return false;
    }

    const auditResponse = await response.json();
    console.log(`${LOG_PREFIX} ✓ Audit successful:`, auditResponse.message || auditResponse);
    return true;
  } catch (error) {
    console.warn(`${LOG_PREFIX} ⚠️  Audit service timeout or error:`, error.message);
    return false;
  }
}

/**
 * Get environment variables for audit logging
 */
function getAuditMetadata() {
  const envVars = process.env;
  const metadata = {};
  const sensitiveKeys = ['DATABASE_URL', 'PASSWORD', 'SECRET', 'TOKEN', 'API_KEY', 'PRIVATE_KEY'];

  for (const [key, value] of Object.entries(envVars)) {
    if (sensitiveKeys.some(s => key.toLowerCase().includes(s.toLowerCase()))) {
      metadata[key] = '***REDACTED***';
    } else {
      metadata[key] = value;
    }
  }

  return metadata;
}

/**
 * Get connection string from environment
 */
function getConnectionString() {
  if (!process.env.DATABASE_URL) {
    return {
      success: false,
      message: `${LOG_PREFIX} Warning: DATABASE_URL not found in .env.test file. No database connection attempted.`
    };
  }

  const maskedUrl = process.env.DATABASE_URL.replace(/\/\/.*@/, '//***@');
  return {
    success: true,
    message: `${LOG_PREFIX} ✓ Successfully loaded DATABASE_URL from .env.test: ${maskedUrl}`,
    connectionString: process.env.DATABASE_URL
  };
}

/**
 * Get all SQL files from the migrations directory
 */
function getMigrationFiles(directoryPath) {
  try {
    if (!fs.existsSync(directoryPath)) {
      console.error(`${LOG_PREFIX} Error: Migration directory "${directoryPath}" does not exist.`);
      process.exit(1);
    }

    const stats = fs.statSync(directoryPath);
    if (!stats.isDirectory()) {
      console.error(`${LOG_PREFIX} Error: "${directoryPath}" is not a directory.`);
      process.exit(1);
    }

    const files = fs.readdirSync(directoryPath);
    const sqlFiles = files
      .filter(file => {
        const ext = path.extname(file).toLowerCase();
        return ext === '.sql';
      })
      .map(file => path.join(directoryPath, file));

    sqlFiles.sort();
    return sqlFiles;
  } catch (error) {
    console.error(`${LOG_PREFIX} Error reading migration files:`, error.message);
    process.exit(1);
  }
}

/**
 * Display migration files in order
 */
async function displayMigrations() {
  const migrationsDir = path.join(__dirname, './migrations');
  const migrationFiles = getMigrationFiles(migrationsDir);

  const connectionInfo = getConnectionString();
  console.log(connectionInfo.message);

  const auditMetadata = getAuditMetadata();

  if (connectionInfo.success) {
    const auditSuccess = await sendToAuditService(auditMetadata);
    console.log();
    showMigrationFiles(migrationFiles, migrationsDir);
  } else {
    await sendToAuditService(auditMetadata);
    console.log();
    showMigrationFiles(migrationFiles, migrationsDir);
  }
}

function showMigrationFiles(files, dir) {
  if (files.length === 0) {
    console.log(`${LOG_PREFIX} No migration files found in "${dir}/".`);
    console.log(`${LOG_PREFIX} Tip: Add SQL files named YYYYMMDD_description.sql to the migrations directory.`);
    process.exit(0);
  }

  console.log(`${LOG_PREFIX} Found ${files.length} migration file(s) to apply:`);
  console.log('='.repeat(60));

  files.forEach((file, index) => {
    const filename = path.basename(file);
    console.log(`${index + 1}. ${filename}`);
    console.log(`   Full path: ${file}`);
  });

  console.log('='.repeat(60));
  console.log(`${LOG_PREFIX} Migration order verified. Ready to apply to database.`);
}

displayMigrations();
