const http = require('http');

const SERVER_PORT = 47301;

const server = http.createServer((req, res) => {
  // Handle CORS
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  if (req.method === 'OPTIONS') {
    res.writeHead(204);
    res.end();
    return;
  }

  if (req.method !== 'POST') {
    res.writeHead(405, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Method not allowed' }));
    return;
  }

  let body = '';

  req.on('data', chunk => {
    body += chunk.toString();
  });

  req.on('end', () => {
    if (!body.trim()) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Empty request body' }));
      return;
    }

    try {
      const data = JSON.parse(body);
      console.log('Received audit payload:');
      console.log(JSON.stringify(data, null, 2));
      console.log('');

      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({
        status: 'ok',
        message: 'Audit logged successfully',
        receivedAt: new Date().toISOString()
      }));
    } catch (err) {
      res.writeHead(400, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ error: 'Invalid JSON' }));
    }
  });
});

server.listen(SERVER_PORT, () => {
  console.log(`Audit service running on http://localhost:${SERVER_PORT}/api/audit`);
  console.log('Listening for POST requests...');
});

server.on('error', (err) => {
  if (err.code === 'EADDRINUSE') {
    console.error(`Port ${SERVER_PORT} is already in use`);
  } else {
    console.error('Server error:', err);
  }
  process.exit(1);
});

#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script that reads SQL files from ./migrations/
 * and logs the filenames it would apply in order.
 */
function migrate() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error('Error: ./migrations/ directory does not exist.');
    console.error('Please create the migrations directory and place your SQL files there.');
    process.exit(1);
  }

  // Read files from migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files
  const sqlFiles = files.filter(file => {
    return file.endsWith('.sql');
  });

  if (sqlFiles.length === 0) {
    console.log('No SQL files found in ./migrations/ directory.');
    return;
  }

  // Sort files alphabetically
  sqlFiles.sort((a, b) => a.localeCompare(b));

  // Log the files to apply
  console.log(`\n📝 Migration Plan for ${sqlFiles.length} file(s):\n`);

  console.log('=================================');
  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
  console.log('=================================');

  console.log('\n💡 Apply these migrations using your database client:');
  console.log(`   mysql -u username -p database_name < ./migrations/${sqlFiles[0]}`);
  console.log('\n');

  // Optionally export the array of migration files
  process.exit(0);
}

// Run the migration function
migrate();

