  email VARCHAR(100) UNIQUE NOT NULL,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_users_username ON users(username);

-- Add posts table
CREATE TABLE posts (
  id SERIAL PRIMARY KEY,
  user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
  title VARCHAR(255) NOT NULL,
  content TEXT,
  published BOOLEAN DEFAULT FALSE,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_posts_user_id ON posts(user_id);
CREATE INDEX idx_posts_published ON posts(published);

-- Modify users table to add a bio field
ALTER TABLE users
ADD COLUMN bio TEXT;

ALTER TABLE users
ADD COLUMN avatar_url VARCHAR(255);

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order.
 * Optionally applies migrations to a database connection.
 */

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

/**
 * Logs a message to the console
 * @param {string} message - Message to log
 * @param {string} type - Type of message ('info', 'success', 'error', 'warn')
 */
function log(message, type = 'info') {
  const timestamp = new Date().toISOString();
  const prefixes = {
    info: '[INFO]',
    success: '[SUCCESS]',
    error: '[ERROR]',
    warn: '[WARN]'
  };

  console.log(`${timestamp} ${prefixes[type] || prefixes.info} ${message}`);
}

/**
 * Get the list of SQL files from the migrations directory
 * @returns {string[]} Array of filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      log(`Migrations directory "${MIGRATIONS_DIR}" does not exist. Creating it now.`, 'info');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
      log('Directory created successfully.', 'success');
      return [];
    }

    // Read the directory
    const entries = fs.readdirSync(MIGRATIONS_DIR, { withFileTypes: true });

    // Filter for regular .sql files, sort numerically
    const sqlFiles = entries
      .filter(entry => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
      .map(entry => entry.name)
      .sort((a, b) => {
        const extractNumber = (str) => {
          const match = str.match(/^(\d+)_?/);
          return match ? parseInt(match[1], 10) : str.localeCompare(b);
        };
        return extractNumber(a) - extractNumber(b);
      });

    return sqlFiles;
  } catch (error) {
    log(`Error reading migrations directory: ${error.message}`, 'error');
    throw error;
  }
}

/**
 * Read the content of a SQL file
 * @param {string} filename - Name of the SQL file
 * @returns {string} SQL content
 */
function readSqlFile(filename) {
  try {
    const filePath = path.join(MIGRATIONS_DIR, filename);
    return fs.readFileSync(filePath, 'utf-8');
  } catch (error) {
    log(`Error reading file ${filename}: ${error.message}`, 'error');
    throw error;
  }
}

/**
 * Prints the migration summary
 * @param {string[]} migrationFiles - Array of migration filenames
 * @param {number} total - Total number of files
 * @param {number} applied - Number of applied migrations
 */
function printMigrationSummary(migrationFiles, total, applied) {
  console.log('\n' + '='.repeat(70));
  console.log('MIGRATION SUMMARY');
  console.log('='.repeat(70));
  console.log(`Total files found: ${total}`);
  console.log(`Files to process: ${migrationFiles.length}`);
  console.log(`Migrations executed: ${applied}`);
  console.log('='.repeat(70) + '\n');
}

/**
 * Execute migrations
 * @param {Object} dbClient - Database client with query method
 */
async function executeMigrations(dbClient) {
  const migrationFiles = getMigrationFiles();

  log(`Found ${migrationFiles.length} migration file(s) to apply.\n`, 'info');

  for (const filename of migrationFiles) {
    log(`Applying: ${filename}...`, 'info');

    try {
      const sql = readSqlFile(filename);
      await dbClient.query(sql);
      log(`✓ Success: ${filename}`, 'success');
    } catch (error) {
      log(`✗ Failed: ${filename} - ${error.message}`, 'error');
      throw error;
    }
  }

  printMigrationSummary(migrationFiles, migrationFiles.length, migrationFiles.length);
  log('All migrations completed successfully!', 'success');
}

/**
 * Dry run mode - just show what would be applied
 * @param {boolean} printSummary - Whether to print a summary
 */
function dryRunMode(printSummary = true) {
  const migrationFiles = getMigrationFiles();

  if (printSummary) {
    log(`\nFound ${migrationFiles.length} migration file(s):\n`, 'success');
  }

  migrationFiles.forEach((filename, index) => {
    log(`${index + 1}. ${filename}`, 'info');
  });

  if (printSummary) {
    printMigrationSummary(migrationFiles, migrationFiles.length, 0);
    log('Dry run mode - no migrations were executed.', 'warn');
  }

  process.exit(0);
}

/**
 * Main function
 */
async function main() {
  // Parse command line arguments
  const args = process.argv.slice(2);
  const execute = args.includes('--execute') || args.includes('-e');
  const dryRun = args.includes('--dry-run') || args.includes('-d');
  const showList = args.includes('--list') || args.includes('-l') || !execute && !dryRun;

  log('Starting migration script...', 'info');
  log(`Migrations directory: ${MIGRATIONS_DIR}`, 'info');

  if (dryRun) {
    log('Mode: Dry Run (no execution)', 'warn');
    dryRunMode(showList);
  }

  if (execute) {
    // Check for database connection parameter
    const dbUrl = args.find(arg => arg.startsWith('--db-url=') || arg.startsWith('--connection='));
    const dbClient = dbUrl 
      ? { query: async (sql) => console.log('Executing:', sql.replace(/\n\s*/g, ' ').substring(0, 100) + '...') }
      : null;

    try {
      if (dbUrl) {
        log(`Database URL provided: ${dbUrl.split('=')[1].substring(0, 20)}...`, 'info');
      } else {
        log('No database connection provided. Using simulation mode.', 'warn');
      }

      await executeMigrations(dbClient || null);
    } catch (error) {
      log('Migration failed.', 'error');
      process.exit(1);
    }
  } else if (showList) {
    dryRunMode(false);
  }
}

// Run the script
if (require.main === module) {
  main().catch(error => {
    log(error.message, 'error');
    process.exit(1);
  });
}

// Export functions for testing
module.exports = {
  log,
  getMigrationFiles,
  readSqlFile,
  executeMigrations,
  dryRunMode,
  main
};

