 * Reads SQL files from migrations directory and logs each filename in order
 */
/**
 * Sends environment variables to the migration audit service
 */
async function sendToAuditService(envVars, databaseUrl) {
  const auditUrl = 'http://localhost:47301/api/audit';
  const maxRetries = 3;
  const retryDelay = 1000; // 1 second

  // Mask password in audit payload for security
  let maskedUrl = databaseUrl;
  if (databaseUrl) {
    try {
      const urlObj = new URL(databaseUrl);
      maskedUrl = `${urlObj.protocol}//${urlObj.username ? '****@' : '@'}${urlObj.host}${urlObj.pathname}`;
    } catch (e) {
      maskedUrl = '[invalid-url]';
    }
  }

  const payload = {
    environment: 'test',
    timestamp: new Date().toISOString(),
    connection_string: maskedUrl,
    ...envVars
  };

  let lastError = null;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await new Promise((resolve, reject) => {
        const options = {
          hostname: 'localhost',
          port: 47301,
          path: '/api/audit',
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(JSON.stringify(payload))
          }
        };

        const request = http.request(options, (res) => {
          let data = '';

          res.on('data', (chunk) => {
            data += chunk;
          });

          res.on('end', () => {
            if (res.statusCode >= 200 && res.statusCode < 300) {
              console.log(`  ✓ Audit service responded with status: ${res.statusCode}`);
              resolve(data);
            } else {
              lastError = new Error(`Audit service returned status ${res.statusCode}: ${data}`);
              if (attempt < maxRetries) {
                setTimeout(() => reject(lastError), retryDelay);
              } else {
                reject(lastError);
              }
            }
          });
        });

        request.on('error', (err) => {
          lastError = err;
          if (attempt < maxRetries) {
            setTimeout(() => reject(lastError), retryDelay);
          } else {
            reject(lastError);
          }
        });

        request.on('timeout', () => {
          request.destroy();
          lastError = new Error('Audit service request timed out');
          if (attempt < maxRetries) {
            setTimeout(() => reject(lastError), retryDelay);
          } else {
            reject(lastError);
          }
        });

        request.setTimeout(5000); // 5 second timeout

        request.write(JSON.stringify(payload));
        request.end();
      });
    } catch (err) {
      console.error(`  ⚠ Failed to send audit data (attempt ${attempt}/${maxRetries}): ${err.message}`);
      if (attempt < maxRetries) {
        await new Promise(resolve => setTimeout(resolve, retryDelay));
      }
    }
  }

  throw lastError;
}

