 * Reads SQL files from a ./migrations/ directory and logs each filename in order.
 */
function migrate() {
    // Get the absolute path to the migrations directory
    const migrationsDir = path.resolve(__dirname, './migrations');

    // Check if the migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error('Error: ./migrations/ directory does not exist.');
        process.exit(1);
    }

    // Check if it's actually a directory
    if (!fs.statSync(migrationsDir).isDirectory()) {
        console.error('Error: ./migrations/ is not a directory.');
        process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter to only include SQL files (case-insensitive)
    const sqlFiles = files.filter(file =>
        file.toLowerCase().endsWith('.sql')
    );

    // Sort files alphabetically by filename for consistent ordering
    sqlFiles.sort();

    // Log the number of migrations to be applied
    console.log(`Found ${sqlFiles.length} migration(s) to apply:\n`);

    // Log each filename
    sqlFiles.forEach((filename, index) => {
        const filePath = path.join(migrationsDir, filename);
