function loadEnvFile() {
  const envPath = path.join(process.cwd(), '.env.test');

  if (!fs.existsSync(envPath)) {
    console.warn('⚠️  WARNING: .env.test file not found');
    console.warn('   Using default environment variables.');
    return;
  }

  try {
    // Read and parse .env.test file manually
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse KEY=VALUE pairs
      const [key, ...valueParts] = trimmedLine.split('=');
      if (key && valueParts.length > 0) {
        const value = valueParts.join('='); // Handle values with '=' sign
        process.env[key.trim()] = value.trim();
      }
    }

    console.log('✅ Successfully loaded environment variables from .env.test');
  } catch (error) {
    console.warn('⚠️  WARNING: Failed to load .env.test:', error.message);
  }
}

