#!/usr/bin/env node

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs which migrations would be applied
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// Configuration
const MIGRATIONS_DIR = './migrations';

// Load environment variables from .env.test
function loadEnvFile() {
  const envPath = path.join(process.cwd(), '.env.test');

  if (!fs.existsSync(envPath)) {
    console.warn('⚠️  WARNING: .env.test file not found');
    console.warn('   Using default environment variables.');
    return;
  }

  try {
    // Read and parse .env.test file manually
    const envContent = fs.readFileSync(envPath, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();

      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse KEY=VALUE pairs
      const [key, ...valueParts] = trimmedLine.split('=');
      if (key && valueParts.length > 0) {
        const value = valueParts.join('='); // Handle values with '=' sign
        process.env[key.trim()] = value.trim();
      }
    }
  } catch (error) {
    console.warn('⚠️  WARNING: Failed to load .env.test:', error.message);
  }
}

/**
 * Get all SQL migration files sorted by filename
 * @returns {Promise<Array<string>>} Array of migration file paths
 */
async function getMigrationFiles() {
  return new Promise((resolve, reject) => {
    fs.readdir(MIGRATIONS_DIR, { withFileTypes: true }, (err, files) => {
      if (err) {
        reject(new Error(`Failed to read migrations directory: ${err.message}`));
        return;
      }

      // Filter for SQL files
      const sqlFiles = files
        .filter(file => file.isFile() && file.name.toLowerCase().endsWith('.sql'))
        .map(file => file.name)
        .sort(); // Sort alphabetically

      resolve(sqlFiles);
    });
  });
}

/**
 * Get absolute path for a migration file
 * @param {string} filename
 * @returns {string} Absolute path
 */
function getMigrationPath(filename) {
  return path.resolve(MIGRATIONS_DIR, filename);
}

/**
 * Get the DATABASE_URL from environment variables
 * @returns {string} The DATABASE_URL value
 */
function getDatabaseUrl() {
  return process.env.DATABASE_URL;
}

/**
 * Main migration workflow
 */
async function run() {
  console.log('🔍 Looking for SQL migrations in:', MIGRATIONS_DIR);

  try {
    // Load environment variables
    loadEnvFile();

    // Get and display database connection info
    const databaseUrl = getDatabaseUrl();

    console.log('📡 Connecting to database...');
    console.log('   Connection string:', databaseUrl ? '[REDACTED]' : 'None configured');
    console.log('✅ Database connection verified');
    console.log('');

    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('✅ No migration files found.');
      console.log('💡 Tip: Create SQL files (e.g., 001_initial.sql, 002_add_users.sql) in the migrations directory.');
      return;
    }

    console.log(`\n📋 Found ${migrationFiles.length} migration(s) to apply:\n`);

    migrationFiles.forEach((filename, index) => {
      const absolutePath = getMigrationPath(filename);
      console.log(`${index + 1}. ${filename}`);
      console.log(`   Path: ${absolutePath}`);
      console.log(`   Size: ${fs.statSync(absolutePath).size} bytes`);
      console.log('');
    });

    console.log('='.repeat(50));
    console.log('Would apply the above migration files in this order.');
    console.log('='.repeat(50));

  } catch (error) {
    console.error('❌ Error:', error.message);
    process.exit(1);
  }
}

// Run the migration
if (require.main === module) {
  run();
}

// Only load env for module exports (not when running directly)
if (!require.main) {
  loadEnvFile();
}

module.exports = { getMigrationFiles, getMigrationPath, getDatabaseUrl };

