#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * This script reads SQL files from the ./migrations/ directory and logs
 * their filenames in alphabetical order.
 * 
 * Usage: node migrate.js
 */

// Configuration
const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL files from the migrations directory
 * @returns {Array} Array of file paths sorted alphabetically
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`❌ Migrations directory not found: ${MIGRATIONS_DIR}`);
    console.log('   Please create the migrations directory first.');
    process.exit(1);
  }

  // Check if it's actually a directory
  if (!fs.statSync(MIGRATIONS_DIR).isDirectory()) {
    console.log(`❌ Path exists but is not a directory: ${MIGRATIONS_DIR}`);
    process.exit(1);
  }

  // Get all files in the directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .map(file => path.join(MIGRATIONS_DIR, file));

  // Sort alphabetically
  sqlFiles.sort((a, b) => {
    return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
  });

  return sqlFiles;
}

/**
 * Display the migration files to be applied
 */
function showPendingMigrations() {
  const files = getMigrationFiles();

  if (files.length === 0) {
    console.log('✅ No migration files found in ./migrations/');
    console.log('   The database is up to date.');
    return;
  }

  console.log('📊 Database Migration Summary');
  console.log('═'.repeat(40));
  console.log(`Found ${files.length} migration file(s) to apply:\n`);

  files.forEach((file, index) => {
    const basename = path.basename(file);
    console.log(`${index + 1}. ${basename}`);
  });

  console.log('\n' + '═'.repeat(40));
}

/**
 * Apply the migration files (placeholder for actual implementation)
 * This function currently just logs the files without executing them.
 */
function applyMigrations() {
  const files = getMigrationFiles();

  if (files.length === 0) {
    console.log('\n✅ No migrations to apply.');
    return;
  }

  console.log('\n📝 Applying migrations...\n');

  files.forEach((file, index) => {
    const basename = path.basename(file);
    // This is where you would actually execute the SQL file
    // Example: fs.readFileSync(file, 'utf8')
    console.log(`   [${index + 1}/${files.length}] Applying: ${basename}`);
  });

  console.log('\n✅ All migrations applied successfully!\n');
}

// Parse command line arguments
const args = process.argv.slice(2);

function main() {
  if (args.includes('--help') || args.includes('-h')) {
    console.log('Usage: node migrate.js [options]');
    console.log('\nOptions:');
    console.log('  --show      Show pending migrations without applying (default)');
    console.log('  --apply     Show and execute the migrations');
    console.log('  --help      Display this help message');
    console.log('\nExample:');
    console.log('  node migrate.js              # Show pending migrations');
    console.log('  node migrate.js --apply       # Apply migrations');
    process.exit(0);
  }

  const apply = args.includes('--apply');

  if (apply) {
    applyMigrations();
  } else {
    showPendingMigrations();
  }
}

// Run the script
main();

