#!/usr/bin/env node

/**
 * Database Migration Script
 *
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * in alphabetical order, indicating which migrations would be applied.
 *
 * Usage: node migrate.js
 */

const fs = require('fs');
const path = require('path');

/**
 * Get all .sql files from the migrations directory, sorted alphabetically
 */
function getMigrationFiles() {
  const migrationsDir = path.join(__dirname, 'migrations');

  try {
    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
      console.error('❌ Error: migrations/ directory not found.');
      console.error(`   Expected at: ${migrationsDir}`);
      process.exit(1);
    }

    // Read directory and filter for .sql files
    const files = fs.readdirSync(migrationsDir)
      .filter((file) => file.endsWith('.sql'))
      .sort(); // Sort alphabetically for predictable application order

    return files;
  } catch (error) {
    console.error('❌ Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Main execution function
 */
function main() {
  console.log('🚀 Starting migration check...');
  console.log('📁 Scanning for SQL files in ./migrations/...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('ℹ️  No migration files found.');
    process.exit(0);
