#!/usr/bin/env node

/**
 * Database Migration Script
 *
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * in alphabetical order, indicating which migrations would be applied.
 *
 * Usage: node migrate.js
 */

const fs = require('fs');
const path = require('path');

// Allow migrations directory to be specified via environment variable
const MIGRATIONS_DIR = process.env.MIGRATIONS_DIR;
const MIGRATIONS_DIR_ABSOLUTE = MIGRATIONS_DIR
  ? path.join(process.cwd(), MIGRATIONS_DIR)
  : path.join(__dirname, 'migrations');

// Load project root for .env.test lookup
const projectRoot = process.cwd();

/**
 * Get all .sql files from the migrations directory, sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR_ABSOLUTE)) {
      console.error('❌ Error: migrations/ directory not found.');
      console.error(`   Expected at: ${MIGRATIONS_DIR_ABSOLUTE}`);

      // Suggest custom path if using MIGRATIONS_DIR env var
      if (MIGRATIONS_DIR) {
        console.error(`\n💡 Use MIGRATIONS_DIR to specify a custom path:`);
        console.error(`   MIGRATIONS_DIR=${MIGRATIONS_DIR} node migrate.js\n`);
      }
      process.exit(1);
    }

    // Read directory and filter for .sql files
    const files = fs.readdirSync(MIGRATIONS_DIR_ABSOLUTE)
      .filter((file) => file.endsWith('.sql'))
      .sort(); // Sort alphabetically for predictable application order

    return files;
  } catch (error) {
    console.error('❌ Error reading migrations directory:', error.message);
    process.exit(1);
  }
}

/**
 * Resolve DATABASE_URL from environment or .env.test file
 */
function resolveDatabaseUrl() {
  // First, check environment variables
  if (MIGRATIONS_DIR && process.env.DATABASE_URL) {
    return process.env.DATABASE_URL;
  }

  // Try to load .env.test file (only if not already using DATABASE_URL from env)
  try {
    const envPath = path.join(projectRoot, '.env.test');
    if (fs.existsSync(envPath)) {
      const envContent = fs.readFileSync(envPath, 'utf-8');

      // Parse .env.test file contents
      for (const line of envContent.split('\n')) {
        const trimmedLine = line.trim();
        if (trimmedLine && !trimmedLine.startsWith('#')) {
          const [key, ...valueParts] = trimmedLine.split('=');
          if (key.trim() === 'DATABASE_URL' && valueParts.length > 0) {
            const value = valueParts.join('=').trim().replace(/^["']|["']$/g, '');
            return value;
          }
        }
      }
    }
  } catch (error) {
    // Log warning but don't fail - fall back to env variable
    console.warn('⚠️  Warning: Could not read .env.test file');
    console.warn(`   Reason: ${error.message}`);
  }

  // Fall back to environment variable
  if (MIGRATIONS_DIR && !process.env.DATABASE_URL) {
    console.error('❌ Error: No DATABASE_URL found in environment or .env.test');
    process.exit(1);
  }

  return process.env.DATABASE_URL;
}

/**
 * Helper to clean and mask the connection string for logging
 */
function maskConnectionUrl(url) {
  try {
    try {
      const urlObj = new URL(url);
      // Mask username/password
      const maskedUrl = urlObj.origin + urlObj.pathname;
      return maskedUrl + '...';
    } catch (e) {
      // If URL parsing fails, just truncate after protocol
      if (url.includes('//')) {
        const parts = url.split('//');
        return parts[0] + '//' + parts.slice(1).join('//').replace(/:[^:@]+/, ':***REDACTED***');
      }
    }
  } catch (error) {
    return url.length > 30 ? url.substring(0, 30) + '...' : url;
  }
  return url;
}

/**
 * Main execution function
 */
function main() {
  console.log('🚀 Starting migration check...\n');

  // Resolve database connection string
  console.log('🔗 Connecting to database...');
  try {
    const dbUrl = resolveDatabaseUrl();
    const maskedUrl = maskConnectionUrl(dbUrl);

    // Log the connection information
    console.log(`   ✓ Connected successfully`);
    console.log(`   📊 Source: ${dbUrl.includes(',') ? 'Environment variable' : '.env.test file'}`);
    console.log(`   🔗 Connection string: ${maskedUrl}\n`);
  } catch (error) {
    console.error(`   ❌ Failed to resolve database connection string`);
    console.error(`   Reason: ${error.message}\n`);
    process.exit(1);
  }

  console.log('📁 Scanning for SQL files in ./migrations/...\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('ℹ️  No migration files found.');
    process.exit(0);
  }

  console.log(`📝 Found ${migrationFiles.length} migration file${migrationFiles.length !== 1 ? 's' : ''}:\n`);

  migrationFiles.forEach((filename, index) => {
    const filePath = path.join(MIGRATIONS_DIR_ABSOLUTE, filename);
    const fileStats = fs.statSync(filePath);
    const fileSize = fileStats.size;
    const formattedSize = formatFileSize(fileSize);

    // Use different indicator for index 0 (first migration)
    const isFirst = index === 0;
    const arrow = isFirst ? '▶' : '•';

    console.log(`  ${arrow} [${String(index + 1).padStart(2)}] ${filename} (${formattedSize})`);
  });

  console.log('\n✅ Migration check complete.');
}

/**
 * Format file size in human-readable format (KB/MB)
 */
function formatFileSize(bytes) {
  if (bytes < 1024) {
    return `${bytes} B`;
  }
  const kb = bytes / 1024;
  if (kb < 1024) {
    return `${kb.toFixed(2)} KB`;
  }
  const mb = kb / 1024;
  return `${mb.toFixed(2)} MB`;
}

// Run the script
if (require.main === module) {
  main();
}

module.exports = { getMigrationFiles, resolveDatabaseUrl, main };

