    const urlParts = url.split('//');
    if (urlParts.length >= 2) {
      const protocol = urlParts[0] || '';
      const rest = urlParts.slice(1).join('//');
      const pathParts = rest.split('/');
      const fullHost = pathParts.shift() || '';

      // Mask credentials in fullHost if present (username:password@host)
      let maskedHost = fullHost;
      if (fullHost.includes('@')) {
        const authParts = fullHost.split('@');
        const host = authParts[authParts.length - 1];
        const auth = authParts.slice(0, authParts.length - 1).join('@');
        const maskedAuth = auth.includes(':') ? auth.split(':')[0] + ':***REDACTED***' : auth;
        maskedHost = maskedAuth.startsWith('http') ? maskedHost : maskedAuth + '@' + host;
      }

      return `${protocol}//${maskedHost}/${pathParts.join('/')}...`;
    }
  } catch (error) {
    // If URL parsing fails, just truncate
  }
  return url.length > 30 ? url.substring(0, 30) + '...' : url;
}

