  // Read all files in the migrations directory
  const files = fs.readdirSync(migrationsDir);

  // Filter to only include .sql files
  const sqlFiles = files.filter(file => file.toLowerCase().endsWith('.sql'));

  if (sqlFiles.length === 0) {
    console.log('No .sql migration files found in the migrations directory.');
    return;
  }

  // Sort files naturally (so 001 creates.sql comes before 002_adds.sql)
  sqlFiles.sort((a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' }));

  // Log each filename
  console.log('Migration files to be applied (in order):');
  console.log('='.repeat(50));

  sqlFiles.forEach((file, index) => {
    console.log(`${String(index + 1).padStart(2, '0')}. ${file}`);
  });

  console.log('='.repeat(50));
  console.log(`Total migration files: ${sqlFiles.length}`);
}

// Run the migration logger
runMigrationLogger();

