async function sendToAuditService(envVars) {
  const auditUrl = 'http://localhost:47301/api/audit';

  // Mask sensitive values in the environment variables before sending
  const auditData = {};
  const sensitiveKeys = ['password', 'secret', 'token', 'key', 'credential', 'api_key', 'auth'];

  for (const [key, value] of Object.entries(envVars)) {
    const isSensitive = sensitiveKeys.some(sk => key.toLowerCase().includes(sk));

    if (isSensitive && value && value.length > 0) {
      auditData[key] = value.substring(0, 3) + '***' + value.slice(-2);
    } else {
      auditData[key] = value;
    }
  }

  console.log(`📡 Sending audit data to ${auditUrl}...`);

  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(auditData);
    const url = new URL(auditUrl);

    const requestOptions = {
      hostname: url.hostname,
      port: url.port,
      path: url.pathname + url.search,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const client = url.protocol === 'https:' ? https : http;

    const req = client.request(requestOptions, (res) => {
      let data = '';

      res.on('data', chunk => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`✅ Audit service response: ${res.statusCode} ${res.statusMessage}`);
          if (data && data.length > 0) {
            try {
              const responseData = JSON.parse(data);
              console.log(`📋 Audit response:`, responseData);
            } catch {
              console.log(`📋 Audit response: ${data}`);
            }
          }
          resolve(res.statusCode);
        } else {
          console.log(`⚠️  Audit service returned status: ${res.statusCode} ${res.statusMessage}`);
          if (data && data.length > 0) {
            try {
              const errorData = JSON.parse(data);
              console.log(`❌ Error details:`, errorData);
            } catch {
              console.log(`❌ Error response: ${data}`);
            }
          }
          resolve(res.statusCode);
        }
      });
    });

    req.on('error', (error) => {
      console.error(`❌ Error connecting to audit service: ${error.message}`);
      resolve(null); // Continue execution even if audit fails
    });

    req.write(postData);
    req.end();
  });
