#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from a ./migrations/ directory and logs each filename it would apply
 */
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Check if a file is a valid SQL file
 * @param {string} filename - The filename to check
 * @returns {boolean} - True if the file appears to be a SQL file
 */
function isValidSqlFile(filename) {
    const ext = path.extname(filename).toLowerCase();
    return ['.sql'].includes(ext);
}

/**
 * Check if a file has already been applied
 * @param {string} filename - The filename to check
 * @returns {boolean} - True if the file has been applied
 */
function isFileApplied(filename) {
    const appliedDir = path.join(__dirname, 'applied');
    if (!fs.existsSync(appliedDir)) {
        return false;
    }
    const appliedFile = path.join(appliedDir, `${filename}.applied`);
    return fs.existsSync(appliedFile);
}

/**
 * Mark a migration as applied
 * @param {string} filename - The filename to mark as applied
 */
function markAsApplied(filename) {
    const appliedDir = path.join(__dirname, 'applied');
    if (!fs.existsSync(appliedDir)) {
        fs.mkdirSync(appliedDir, { recursive: true });
    }
    const appliedFile = path.join(appliedDir, `${filename}.applied`);
    fs.writeFileSync(appliedFile, new Date().toISOString());
}

/**
 * Main migration function
 */
function runMigrations() {
    console.log('🔍 Reading migration files from:', migrationsDir);

    // Check if migrations directory exists
    if (!fs.existsSync(migrationsDir)) {
        console.error('❌ Error: ./migrations/ directory does not exist');
        process.exit(1);
    }

    // Read all files in migrations directory
    const files = fs.readdirSync(migrationsDir);

    // Filter for valid SQL files
    const sqlFiles = files
        .filter(file => isValidSqlFile(file))
        .sort(); // Sort alphabetically to ensure consistent ordering

    if (sqlFiles.length === 0) {
        console.log('✅ No SQL files found in ./migrations/');
        return;
    }

    console.log(`📝 Found ${sqlFiles.length} SQL migration file(s):`);

    let appliedCount = 0;
    let skippedCount = 0;

    sqlFiles.forEach((file, index) => {
        const filePath = path.join(migrationsDir, file);
        const stats = fs.statSync(filePath);
        const isApplied = isFileApplied(file);

        if (isApplied) {
            console.log(`   [${index + 1}/${sqlFiles.length}] ${file} ⏭️  (already applied)`);
            skippedCount++;
        } else {
            console.log(`   [${index + 1}/${sqlFiles.length}] ${file} → Would apply`);
            appliedCount++;
        }
    });

    console.log('\n📊 Summary:');
    console.log(`   Total files found: ${sqlFiles.length}`);
    console.log(`   New migrations to apply: ${appliedCount}`);
    console.log(`   Skipped (already applied): ${skippedCount}`);

    if (appliedCount > 0) {
        console.log('\n💡 Tip: To apply these migrations, execute the SQL files manually');
        console.log(`   or add logic to actually run the SQL statements.`);
    } else {
        console.log('\n✅ All pending migrations have been applied!');
    }
}

// Run migrations
runMigrations();

-- Create users table
CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT NOW()
);

INSERT INTO users (username, email) VALUES ('john_doe', 'john@example.com');

-- Create orders table (depends on users)
CREATE TABLE orders (
    id SERIAL PRIMARY KEY,
    user_id INTEGER REFERENCES users(id),
    total_amount DECIMAL(10, 2) NOT NULL,
    status VARCHAR(20) DEFAULT 'pending',
    created_at TIMESTAMP DEFAULT NOW()
);

INSERT INTO orders (user_id, total_amount, status) VALUES (1, 99.99, 'pending');

