#!/usr/bin/env node

/**
 * Database migration script
 * Reads SQL files from the ./migrations/ directory and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');
const readline = require('readline');

/**
 * Reads and processes migration files from the migrations directory
 */
async function runMigrations() {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error('Error: migrations directory does not exist:', migrationsDir);
    process.exit(1);
  }

  // Read the directory to get all SQL files
  const files = fs.readdirSync(migrationsDir);

  // Filter for .sql files and sort them alphabetically
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found in ./migrations/');
    return;
  }

  console.log(`Found ${sqlFiles.length} migration file(s) to apply:\n`);

  // Log each migration file
  sqlFiles.forEach((file, index) => {
    const filePath = path.join(migrationsDir, file);
    try {
      const stat = fs.statSync(filePath);
      const sizeKB = (stat.size / 1024).toFixed(2);
      const timestamp = stat.mtime.toISOString().split('T')[0] + ' ' + stat.mtime.toTimeString().split(' ')[0];

      console.log(`${index + 1}. ${file}`);
      console.log(`   Size: ${sizeKB} KB`);
      console.log(`   Modified: ${timestamp}\n`);
    } catch (err) {
      console.error(`   Error reading file: ${err.message}`);
    }
  });

  console.log('---');
  console.log('These migrations would be applied in order.');
  console.log('To actually run them against your database, update the runMigrations() function.');
}

// Run the migrations when the script is executed
if (require.main === module) {
  runMigrations().catch(error => {
    console.error('Migration script failed:', error);
    process.exit(1);
  });
}

// Export the function for programmatic use
module.exports = { runMigrations };

