#!/usr/bin/env node

/**
 * Database migration script
 * Reads SQL files from the ./migrations/ directory and logs each filename it would apply, in order.
 *
 * Usage:
 *   node migrate.js                         # Just show what migrations would be applied
 *   node migrate.js --run                   # Apply migrations to database
 *   node migrate.js --run --db=postgresql   # Show migrations then apply using PostgreSQL
 *
 * Dependencies required for --run mode:
 *   npm install pg                           # PostgreSQL
 *   npm install mysql2                       # MySQL / MariaDB
 *   npm install oracledb                     # Oracle
 *
 * Configure DATABASE_URL or specific connection config for your database.
 */

const fs = require('fs');
const path = require('path');
const readline = require('readline');

// Database drivers
let dbClient = null;

/**
 * Initialize database connection based on DATABASE_URL
 */
async function initializeDatabase() {
  const env = process.env;

  // Try to get connection from env or config
  const databaseUrl = env.DATABASE_URL || env.MIGRATION_URL;

  if (!databaseUrl) {
    console.warn('\nNo DATABASE_URL found in environment variables.');
    console.warn('To run migrations, set DATABASE_URL or install a database client.\n');
    return null;
  }

  // Parse database URL to determine driver
  let driverName = 'unknown';
  let config = {};

  if (databaseUrl.startsWith('postgres')) {
    driverName = 'postgresql';
    // Parse postgresql://user:pass@host:port/dbname
    const urlParts = new URL(databaseUrl);
    config = {
      host: urlParts.hostname,
      port: urlParts.port || 5432,
      user: urlParts.username,
      password: urlParts.password,
      database: urlParts.pathname.slice(1), // remove leading '/'
    };
  } else if (databaseUrl.startsWith('mysql') || databaseUrl.startsWith('mariadb')) {
    driverName = 'mysql';
    // Parse mysql://user:pass@host:port/dbname
    const urlParts = new URL(databaseUrl);
    try {
      config = {
        host: urlParts.hostname || 'localhost',
        port: urlParts.port || 3306,
        user: urlParts.username,
        password: urlParts.password,
        database: urlParts.pathname.slice(1),
      };
    } catch (err) {
      // Handle URL parsing failure
      console.warn('Could not parse DATABASE_URL for MySQL. Falling back to manual config.');
    }
  } else if (databaseUrl.startsWith('oracledb://')) {
    driverName = 'oracle';
    config.connectString = databaseUrl.replace('oracledb://', '');
  }

  if (driverName === 'unknown') {
    console.warn('Unsupported DATABASE_URL protocol. Supported postgresql, mysql, mariadb or oracledb.');
    return null;
  }

  // Load appropriate driver
  try {
    let driverModule;
    if (driverName === 'postgresql') {
      driverModule = require('pg');
      dbClient = new driverModule.Pool(config);
    } else if (driverName === 'mysql') {
      driverModule = require('mysql2/promise');
      dbClient = await driverModule.createConnection(config);
    } else if (driverName === 'oracle') {
      driverModule = require('oracledb');
      dbClient = await driverModule.getConnection(config);
    }
    console.log(`✓ Connected to ${driverName} database`);
    return dbClient;
  } catch (err) {
    console.error('Error connecting to database:', err.message);
    return null;
  }
}

/**
 * Apply a single migration file to the database
 */
async function applyMigration(migrationFile, migrationsDir) {
  const filePath = path.join(migrationsDir, migrationFile);

  try {
    // Read SQL content
    const sql = fs.readFileSync(filePath, 'utf-8');

    if (!dbClient) {
      console.log(`[SKIP] ${migrationFile} - No database connection`);
      return false;
    }

    // Execute SQL
    let driver = dbClient;
    let params = [migrationFile];

    if (driver.execQuery && driver.execQuery.bind) {
      // MySQL driver
      await driver.execQuery(sql);
    } else if (driver.execute && driver.execute.bind) {
      // Oracle driver uses execute with binds
      const result = await driver.execute(sql);
      params.push(JSON.stringify(result.rowsAffected));
    } else {
      // PostgreSQL driver and other parameterized query approaches
      await driver.query(sql);
    }

    console.log(`[OK]    Applied ${migrationFile}`);
    return true;
  } catch (err) {
    console.error(`[FAILED] ${migrationFile} - ${err.message}`);
    return false;
  }
}

/**
 * Check if a migration has already been applied (if tracking is supported)
 */
async function isMigrationApplied(migrationFile) {
  // This is a simple implementation. You may want to create a migrations table
  // to track which migrations have been run.
  return false;
}

/**
 * Read and process migration files from the migrations directory
 */
async function runMigrations(runNeeded = false) {
  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error('Error: migrations directory does not exist:', migrationsDir);
    process.exit(1);
  }

