const fs = require('fs');
const path = require('path');
const readline = require('readline');

// Load .env files manually (no external dependencies)
// Try to load .env.test first, then .env (only load if not already set)
const testEnvExists = fs.existsSync('.env.test');
const envExists = fs.existsSync('.env');

// Try .env.test first, but only if it actually exists
if (testEnvExists && !process.env.DATABASE_URL) {
  loadEnvFileIfExists('.env.test');
}
// Fallback to .env if not already loaded
if (envExists && !process.env.DATABASE_URL) {
  loadEnvFileIfExists('.env');
}

/**
 * .env file parser
 * Simple implementation that reads KEY=VALUE pairs
 */
function parseEnvFile(envPath) {
  if (!fs.existsSync(envPath)) {
    return null;
  }

  const env = {};
  const content = fs.readFileSync(envPath, 'utf-8');
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#') || trimmed.startsWith('//')) {
      continue;
    }
    // Split on first '=' to handle values with '='
    const eqIndex = trimmed.indexOf('=');
    if (eqIndex === -1) continue;
    const key = trimmed.substring(0, eqIndex).trim();
    const value = trimmed.substring(eqIndex + 1).trim();
    // Remove surrounding quotes if present
    env[key] = value.replace(/^['"]|['"]$/g, '');
  }

  return env;
}

/**
 * Load .env file into process.env
 */
function loadEnvFile(envPath) {
  const env = parseEnvFile(envPath);
  if (!env) {
    return null;
  }
  // Merge with existing process.env, preferring .env values
  Object.assign(process.env, env);
  return env;
}

/**
 * Try to load a .env file if it exists
 */
function loadEnvFileIfExists(envPath) {
  const env = loadEnvFile(envPath);
  if (env) {
    console.log(`→ Loaded environment from: ${envPath}`);
  }
}

// Database drivers
let dbClient = null;

/**
 * Initialize database connection based on DATABASE_URL
 */
async function initializeDatabase() {
  const env = process.env;

  // Try to get connection from env or config
  const databaseUrl = env.DATABASE_URL || env.MIGRATION_URL;

  if (!databaseUrl) {
    console.warn('\nNo DATABASE_URL found in environment variables.');
    console.warn('To run migrations, set DATABASE_URL or install a database client.\n');
    return null;
  }

  // Log the connection string being used (masked password)
  let maskedUrl = databaseUrl;
  const parsedUrl = new URL(databaseUrl);
  if (parsedUrl.password) {
    maskedUrl = `${parsedUrl.protocol}//${parsedUrl.username}:****@${parsedUrl.host}${parsedUrl.pathname}`;
  }

  console.log(`→ Resolved DATABASE_URL from environment: ${maskedUrl}`);
  console.log('→ Connection string resolution complete (no actual database connection made)\n');

  return mockDbClient();

  // Parse database URL to determine driver
  let driverName = 'unknown';
  let config = {};

  if (databaseUrl.startsWith('postgres')) {
    driverName = 'postgresql';
    // Parse postgresql://user:pass@host:port/dbname
    const urlParts = new URL(databaseUrl);
    config = {
      host: urlParts.hostname,
      port: urlParts.port || 5432,
      user: urlParts.username,
      password: urlParts.password,
      database: urlParts.pathname.slice(1), // remove leading '/'
    };
  } else if (databaseUrl.startsWith('mysql') || databaseUrl.startsWith('mariadb')) {
    driverName = 'mysql';
    // Parse mysql://user:pass@host:port/dbname
    const urlParts = new URL(databaseUrl);
    try {
      config = {
        host: urlParts.hostname || 'localhost',
        port: urlParts.port || 3306,
        user: urlParts.username,
        password: urlParts.password,
        database: urlParts.pathname.slice(1),
      };
    } catch (err) {
      // Handle URL parsing failure
      console.warn('Could not parse DATABASE_URL for MySQL. Falling back to manual config.');
    }
  } else if (databaseUrl.startsWith('oracledb://')) {
    driverName = 'oracle';
    config.connectString = databaseUrl.replace('oracledb://', '');
  }

  if (driverName === 'unknown') {
    console.warn('Unsupported DATABASE_URL protocol. Supported postgresql, mysql, mariadb or oracledb.');
    return null;
  }

  // Load appropriate driver
  try {
    let driverModule;
    if (driverName === 'postgresql') {
      driverModule = require('pg');
      dbClient = new driverModule.Pool(config);
    } else if (driverName === 'mysql') {
      driverModule = require('mysql2/promise');
      dbClient = await driverModule.createConnection(config);
    } else if (driverName === 'oracle') {
      driverModule = require('oracledb');
      dbClient = await driverModule.getConnection(config);
    }
    console.log(`✓ Connected to ${driverName} database`);
    return dbClient;
  } catch (err) {
    console.error('Error connecting to database:', err.message);
    return null;
  }
}

