      // Skip empty lines, comments, and lines without =
      if (!line || line.startsWith('#') || !line.includes('=')) {
        return;
      }

      const [key, ...valueParts] = line.split('=');
      const value = valueParts.join('=').trim().replace(/^["']|["']$/g, '');

      environment[key.trim()] = value;
    });

    return environment;
  } catch (error) {
    console.error(`${LOG_PREFIX} Error reading .env.test: ${error.message}`);
    return {};
  }
}

/**
 * Extract database type from connection string
 */
function getDatabaseType(url) {
  if (url.includes('postgresql://') || url.includes('postgres://')) {
    return 'PostgreSQL';
  } else if (url.includes('mysql://') || url.includes('mysql2://') || url.includes('mysql-crdt://')) {
    return 'MySQL';
  } else if (url.includes('sqlite://') || url.includes('file:') || url.endsWith('.db')) {
    return 'SQLite';
  } else {
    return 'Unknown';
  }
}

/**
 * Mask sensitive credentials in connection string
 */
function maskConnectionUrl(url) {
  return url.replace(/\/\/[^:]+:[^@]+@/, '****:****@');
}

/**
 * Main function to run the migration script
 */
async function main() {
  try {
    // Get environment variables
    const env = loadEnvironment();
    const connectionString = env.DATABASE_URL;

    // Log connection
    if (connectionString) {
      const databaseType = getDatabaseType(connectionString);
      const maskedUrl = maskConnectionUrl(connectionString);
      console.log(`${LOG_PREFIX} ✓ Connected to ${databaseType} database: ${maskedUrl}`);
    } else {
      console.log(`${LOG_PREFIX} Configuration: No DATABASE_URL provided`);
      console.log(`${LOG_PREFIX}   Environment file: ${ENV_FILE}`);
      console.log(`${LOG_PREFIX}   Hint: Set DATABASE_URL in .env.test`);
    }

    console.log(''); // Empty line for spacing

    // Ensure migrations directory exists
    await ensureMigrationsDirExists();

    // Read and sort migration files
    const migrationFiles = await getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log(`${LOG_PREFIX} ℹ No migration files found in ${MIGRATIONS_DIR}`);
      console.log(`${LOG_PREFIX} ℹ Example: echo "CREATE TABLE..." > ${MIGRATIONS_DIR}/001_initial.sql`);
      return;
    }

    // Log each migration file
    console.log(`${LOG_PREFIX} Found ${migrationFiles.length} migration file(s):`);
    console.log(`${LOG_PREFIX} ${'-'.repeat(60)}`);

    migrationFiles.forEach((filename, index) => {
      console.log(`${LOG_PREFIX} ${String(index + 1).padStart(2, '0')} | ${filename}`);
    });

    console.log(`${LOG_PREFIX} ${'-'.repeat(60)}`);
    console.log(`${LOG_PREFIX} ✦ This is a DRY RUN - no SQL will be executed`);

  } catch (error) {
    console.error(`${LOG_PREFIX} ❌ Error: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Ensure the migrations directory exists
 */
async function ensureMigrationsDirExists() {
  try {
    await fs.access(MIGRATIONS_DIR);
  } catch {
    // Directory doesn't exist, create it
    await fs.mkdir(MIGRATIONS_DIR, { recursive: true });
    console.log(`${LOG_PREFIX} ✓ Created migrations directory: ${MIGRATIONS_DIR}`);
  }
}

/**
 * Get and sort migration files from the migrations directory
 *
 * Files are ordered by numeric prefix, then alphabetically
 * for files with the same prefix
 */
async function getMigrationFiles() {
  try {
    const files = await fs.readdir(MIGRATIONS_DIR);

    // Filter to only SQL files
    const sqlFiles = files.filter(file => {
      return file.endsWith('.sql') ||
             file.endsWith('.sql.js') ||
             file.endsWith('.up.sql') ||
             file.endsWith('.down.sql');
    });

    // Sort files: prefix digits first, then alphabetical
    return sqlFiles.sort((a, b) => {
      const aMatch = a.match(/^(\d+)/);
      const bMatch = b.match(/^(\d+)/);

      // Files with numeric prefixes come first, ordered by the number
      if (aMatch && bMatch) {
        return parseInt(aMatch[1], 10) - parseInt(bMatch[1], 10);
      }

      // Mixed alphanumeric or all alphabetical - default alphabetical
      return a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' });
    });
  } catch (error) {
    throw new Error(`Failed to read migrations directory: ${error.message}`);
  }
}

// Run the script
if (require.main === module) {
  main();
}

module.exports = { main, loadEnvironment, ensureMigrationsDirExists, getMigrationFiles };

