/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order.
 */

const fs = require('fs');
const path = require('path');

/**
 * Logs a message to the console with a timestamp
 * @param {string} message - The message to log
 */
function log(message) {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] ${message}`);
}

/**
 * Reads SQL files from the migrations directory and logs them in order
 */
async function runMigrations() {
  log('Starting migration process...');

  const migrationsDir = path.join(__dirname, 'migrations');

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    log(`Error: Migrations directory not found at ${migrationsDir}`);
    process.exit(1);
  }

  // Get all SQL files from the directory
  let files = fs.readdirSync(migrationsDir);

  // Filter for SQL files only (by extension)
  const sqlFiles = files.filter(file => {
    const ext = path.extname(file).toLowerCase();
    return ['.sql', '.sql?'].includes(ext);
  });

  // Sort files alphabetically (by filename) to ensure order
  sqlFiles.sort((a, b) => a.localeCompare(b));

  if (sqlFiles.length === 0) {
    log('No SQL files found in migrations directory.');
    return;
  }

  log(`Found ${sqlFiles.length} migration file(s):`);

  // Log each file that would be applied
  sqlFiles.forEach((file, index) => {
    const filePath = path.join(migrationsDir, file);
    const stats = fs.statSync(filePath);

    log(`[${index + 1}/${sqlFiles.length}] Would apply: ${file}`);
    log(`    Size: ${(stats.size / 1024).toFixed(2)} KB`);
    log(`    Location: ${filePath}`);
  });

  log('Migration summary complete.');
  log('');
  log('To actually apply these migrations, you would need to:');
  log('  1. Connect to your database');
  log('  2. Execute each SQL file in order');
  log('  3. Update migration tracking (if applicable)');
}

/**
 * Main execution
 */
async function main() {
  try {
    await runMigrations();
    process.exit(0);
  } catch (error) {
    log(`Error executing migrations: ${error.message}`);
    process.exit(1);
  }
}

// Run the migrations
main();

