const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename to apply in order.
 *
 * Usage: node migrate.js
 */

// Configuration
const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL files from the migrations directory, sorted by filename
 * @returns {Array<string>} Array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`⚠️  Warning: ${MIGRATIONS_DIR}/ directory does not exist.`);
      console.log('   Creating the directory for you...');
      fs.mkdirSync(MIGRATIONS_DIR, { recursive: true });
    }

    // Read directory contents
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    const sqlFiles = files
      .filter(file => file.endsWith('.sql') || file.endsWith('.sql.js'))
      .sort();

    return sqlFiles;
  } catch (error) {
    throw new Error(`Error reading migrations directory: ${error.message}`);
  }
}

/**
 * Log the migration files in order
 */
function logMigrationFiles() {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('ℹ️  No SQL migration files found in ./migrations/ directory.');
    console.log('   Add your migration files (.sql) to the directory and run this script again.');
    return;
  }

  console.log('='.repeat(60));
  console.log('📋 Database Migration Files Found');
  console.log('='.repeat(60));
  console.log(`Total migrations: ${migrationFiles.length}\n`);

  console.log('Migration order:');
  console.log('-'.repeat(60));

  migrationFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });

  console.log('-'.repeat(60));
  console.log(`\n✅ Ready to apply ${migrationFiles.length} migration(s)`);

  // Optional: Uncomment to display migration files with their content
  // showMigrationFilesDetails(migrationFiles);
}

/**
 * Optional: Display full details of migration files
 * @param {Array<string>} files - Array of migration file paths
 */
function showMigrationFilesDetails(files) {
  console.log('\n\nMigration file details:');
  console.log('='.repeat(60));

  files.forEach(file => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n').length;

    console.log(`\n📄 ${file}`);
    console.log(`   Size: ${Math.round(content.length / 1024).toFixed(2)} KB`);
    console.log(`   Lines: ${lines}`);
    console.log(`   Status: Ready to apply`);
  });
}

/**
 * Main execution
 */
function main() {
  try {
    logMigrationFiles();
  } catch (error) {
    console.error(`❌ Error: ${error.message}`);
    process.exit(1);
  }
}

// Run when executed directly
if (require.main === module) {
  main();
}

// Export functions for programmatic use
module.exports = {
  getMigrationFiles,
  logMigrationFiles,
  showMigrationFilesDetails,
};

